import {field,select,panel,table,button,esc,submit,errors,note,levelLabels,runtimeLabel} from './view.js';
export function sampleAdmin(s){
  return panel('Bot mẫu của BTC',`<form class="real-form" id="sample-bot-form">${field('Tên bot','bot-name','required maxlength="80"')}<div class="form-grid"><label class="field"><span>Mức độ</span>${select('bot-level',Object.entries(levelLabels))}</label><label class="field"><span>Ngôn ngữ</span>${select('runtime',[['cpp17','C++17'],['c11','C11'],['python3','Python 3.11 (PyPy)']])}</label></div><label class="field"><span>File ZIP source (giao thức v2)</span><input class="input" name="source" type="file" accept=".zip" required></label>${errors()}${submit('Thêm bot mẫu')}</form>${note('Bot mẫu chỉ dùng để các đội luyện tập, không tham gia giải và không tính điểm. Đội chỉ thấy tên và mức độ, không thấy source hay log của bot mẫu.')}${table(['Bot','Mức độ','Ngôn ngữ',''],(s.sampleBots||[]).map(b=>`<tr><td>${esc(b.name)}</td><td>${esc(levelLabels[b.level]||b.level)}</td><td>${esc(runtimeLabel(b.runtime))}</td><td>${button(b.enabled?'Tắt':'Bật','sample-bot-toggle',`data-id="${b.id}" data-enabled="${!b.enabled}"`,'small')}</td></tr>`))}`);
}
